def build(lang):
 en=lang=='en';T=lambda a,b:a if en else b;E=html.escape
 data=json.loads((ROOT/f'data/catalogue.{lang}.json').read_text());connections=json.loads((ROOT/'data/connections.json').read_text());domains=json.loads((ROOT/f'data/domains.{lang}.json').read_text())
 labels=[T('Purpose','整体结构'),T('Install & run','安装与运行'),T('Agent systems','Agent 接入'),T('Software connections','软件与接口'),T('Research methods','研究方法'),T('Execution & results','任务与结果')];ids=['overview','install','hosts','software','methods','results']
