 headings=[T('Optical research, in operation.','让 Agent 使用光学研究软件。'),T('Use the scientific environment you need.','连接研究所需要的计算环境。'),T('One package. Native host connections.','一个软件包，接入不同的 Agent 系统。'),T('Software, interfaces and execution.','软件、接口与执行能力。'),T('Start from the physical question.','从物理问题选择模型。'),T('Keep research calculations running.','让研究计算持续运行。')]
 def start(i):return f'<section id="{ids[i]}" {"hidden" if i else ""}><div class="tag">{i+1:02} / OPTICS &amp; PHOTONICS</div><h1>{headings[i]}</h1>'
 def code(s):return '<pre><code>'+E(s)+'</code></pre>'
 overview=start(0)+f'<p class="lead">{T("Native optical software, scientific methods and durable calculations in a shared research workflow.","原生光学软件、专业研究方法与持续计算，组成连贯的数字实验流程。")}</p>'
 statlabels=[T('executed libraries','已执行计算的库'),T('native session adapters','原生会话连接器'),T('host package formats','宿主接入格式'),T('MCP tools','MCP 工具')]
