 overview+=f'<div class="grid"><div class="card"><h3>Optics &amp; Photonics</h3><p>{T("Software selection, physical models, native programs, scientific data and host connections.","软件选择、物理模型、原生研究程序、科学数据与宿主接入。")}</p></div><div class="card"><h3>{T("Independent computation","独立计算")}</h3><p>{T("Background workers, parallel and dependent calculations, shared computing resources and saved results.","后台运行、并行与依赖计算、共享计算资源、保存研究结果。")}</p></div></div>'
 overview+=f'<div class="callout"><h2>{T("Keep the full scientific API.","保留科学软件的完整能力。")}</h2><p>{T("An Agent can write a complete research program: build a model, run a solver, optimize parameters and save results. The packaged calculations are starting points; each upstream API remains available.","Agent 可以编写完整研究程序：建立模型、调用求解器、优化参数、保存结果。已提供的计算是入口，每个软件的原生 API 仍然完整可用。")}</p></div>'
 overview+=f'<div class="actions"><button class="button" data-page="install">{T("Install the package","安装软件包")}</button><button class="button secondary" data-page="software">{T("Explore connections","查看软件与接口")}</button></div><p class="note">{T("Connection descriptions cover the current catalogue. Executed libraries and vendor-dependent routes are distinguished in the software view.","连接说明覆盖当前目录；软件页面分别标明已执行计算的库与需要厂商环境的接入方式。")}</p></section>'
 install=start(1)+f'<p class="lead">{T("The connector runs on Windows, macOS and Linux with Python 3.10+. Each solver keeps its own platform and license requirements.","连接器使用 Python 3.10+，运行于 Windows、macOS 和 Linux。具体求解器保留自己的平台与许可要求。")}</p>'
 install+=code('python -m pip install "git+https://github.com/Cherish0925/Optics-Photonics-AI-Lab.git@optics-v'+__version__+'"\noptics-photonics info tmm\noptics-photonics prepare tmm')
 install+=f'<p>{T("Save these inputs as inputs.json. The calculation returns a compact result and a spectrum CSV.","将下面的输入保存为 inputs.json，计算后获得简洁结果和光谱 CSV。")}</p>'+code(json.dumps(EXAMPLES['tmm'][1],indent=2))+code('optics-photonics run tmm spectrum --inputs "@inputs.json"')
 install+=f'<h2>{T("Reuse an installed environment","使用已经安装的科学环境")}</h2>'+code('optics-photonics bind tmm --python /path/to/python --threads 1 --concurrency 4\noptics-photonics environments')
 install+=f'<p>{T("Use a release wheel when Git is unavailable. Prepare creates an isolated environment only for listed recipes; commercial tools, MPI builds and GPU distributions use their own installers. Configuration is kept under OPTICS_HOME or ~/.optics-photonics.","没有 Git 时可以安装发布的 wheel。prepare 为列出的安装配方建立独立环境；商业软件、MPI 与 GPU 版本使用原生安装方法。配置保存在 OPTICS_HOME 或 ~/.optics-photonics。")}</p></section>'
 install=install.removesuffix('</section>')
 install+=f'<h2>{T("Connect installed simulation software","连接已经安装的仿真软件")}</h2>'
