 rows=[('Lumerical','lumapi / PyLumerical','Windows · Linux',T('FDTD, MODE, DEVICE, INTERCONNECT; models and monitor results.','FDTD、MODE、DEVICE、INTERCONNECT；模型与监视器结果。')),('COMSOL','MPh → Java API','Windows · Linux · macOS',T('Parameters, studies, fields and the complete Java API.','参数、研究求解、场数据与完整 Java API。')),('OpticStudio','ZOSPy → ZOS-API','Windows',T('Lens and nonsequential systems, ray tracing and native analyses.','镜头与非序列系统、光线追迹与原生分析。')),('CST','cst.interface / cst.results','Windows · Linux',T('Projects, model history, solvers and result trees.','项目、建模历史、求解器与结果树。'))]
 install+='<div class="table"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in [T('Software','软件'),T('Connection','连接'),T('Execution host','执行系统'),T('Operations','操作')])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
 install+=f'<p>{T("Each background step owns one software session. Its program can build geometry, modify materials, run an optimization loop and export data through the full native API. Work models are saved in the result directory. Discovery and configuration do not launch the licensed solver.","每个后台步骤持有一个软件会话。程序可以通过完整原生 API 建立几何、修改材料、执行优化循环并导出数据；工作模型保存在结果目录。发现与配置阶段不会启动需要许可的求解器。")}</p>'
 install+=f'<p class="note">{T("The connector is checked on three operating systems. Commercial adapters have session-lifecycle checks; licensed solver execution requires the target workstation. Solver and SDK platform support follows the installed version.","连接器经过三个操作系统检查；商业连接器已检查会话生命周期，求解需在具有对应软件与许可的工作站运行。求解器及 SDK 的系统支持取决于安装版本。")} <a href="{T("NATIVE.md","NATIVE.zh-CN.md")}">{T("Native software guide","原生软件接入说明")}</a></p></section>'
 hosts=start(2)+code('optics-photonics connect agentic-research-os --output optics-plugin')
 hostrows=[('Agentic Research OS','agentic-research-os','plugin.json · ${RESEARCH_PYTHON}',T('Install and activate the package revision.','安装插件并激活对应修订。')),('Codex','codex','.codex-plugin · .mcp.json',T('Native plugin or generated MCP registration command.','原生插件或生成的 MCP 注册命令。')),('Claude Code','claude','.claude-plugin · .mcp.json','claude --plugin-dir PATH'),('DeepSeek Harness','deepseek','optics.cordis.yml','dsh web --patch PATH/optics.cordis.yml'),('Qiushi','qiushi','MCP · tools / call',T('Research OS editions use its native package.','基于研究系统的版本使用其原生包。')),('Agent Plugins','portable','plugin.json · mcp.json',T('Install in a host supporting portable Agent Plugins.','用于支持便携 Agent Plugins 格式的宿主。')),('MCP','mcp','mcp.json',T('Register stdio in the host’s format.','按宿主格式注册 stdio。'))]
 hosts+='<div class="table"><table><thead><tr>'+''.join(f'<th>{s}</th>' for s in [T('Host','宿主'),T('Command option','命令选项'),T('Package','包内容'),T('Use','使用')])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(x)+'</td>' for x in row)+'</tr>' for row in hostrows)+'</tbody></table></div>'
 hosts+=f'<div class="grid"><div class="card"><h3>{T("Install once, keep environments","更新插件，保留计算环境")}</h3><p>{T("New connector versions produce a new plugin directory. The host updates its installed package; software environments and saved experiments remain separate.","新版本生成新的插件目录，由宿主完成更新。科学环境和已保存的实验独立保留。")}</p></div><div class="card"><h3>{T("Local and remote execution","本地与远程执行")}</h3><p>{T("Run MCP on the computer with the scientific environment. A remote host can launch it over SSH; calculations and large files remain on the computing machine.","MCP 运行在具有科学软件的计算机上。远程宿主可通过 SSH 启动它，计算和大型文件始终留在计算节点。")}</p></div></div><p class="note">{T("Each generated package includes INSTALL.md with the host command, Python location and update procedure. The same MCP server serves all host packages.","每个生成包均有 INSTALL.md，记录宿主命令、Python 位置与更新方法。所有宿主包使用同一个 MCP 服务。")}</p></section>'
 software=start(3)+f'<p class="lead">{T("Filter by physical domain, license and connection route. Open each record for native interfaces and original sources.","按物理领域、许可与接入方式筛选。展开条目即可查看原生接口与原始资料。")}</p><div class="filters"><input id="query" aria-label="{T("Search software","搜索软件")}" placeholder="{T("Software or physical method…","软件或物理方法…")}"><select id="license"><option value="">{T("All licenses","全部许可")}</option><option value="open">{T("Open source","免费开源")}</option><option value="paid">{T("Commercial","商业付费")}</option><option value="limited">{T("Limited","受限许可")}</option></select><select id="domain"><option value="">{T("All domains","全部领域")}</option>'+''.join(f'<option value="{d[0]}">{E(d[1])}</option>' for d in domains)+f'</select><select id="route"><option value="">{T("All routes","全部接入方式")}</option><option value="executed">{T("Executed libraries","已执行计算")}</option><option value="session">{T("Native sessions","原生会话")}</option><option value="python">Python API</option><option value="native">{T("Native executable","原生命令 / 厂商接口")}</option><option value="manual">{T("Manual / unconfirmed","接口待明确")}</option><option value="data">{T("Data source","数据源")}</option></select></div><p class="count" id="count"></p><div class="softgrid" id="cards"></div></section>'
 methods=start(4)+f'<p class="lead">{T("Choose a representation from the observable, scales, coherence, polarization and material response. Read the methods needed for the current task.","从观测量、尺度、相干性、偏振与材料响应选择物理表示，按当前任务读取需要的方法。")}</p><div class="domains">'+''.join(f'<a href="https://github.com/Cherish0925/Optics-Photonics-AI-Lab/blob/main/skills/optical-research/references/{d[0]}.md"><strong>{E(d[1])}</strong><span>{E(d[2])}</span></a>' for d in domains)+'</div>'
 methods+=f'<div class="callout"><h2>{T("Pass physical quantities, not just files.","软件之间传递的是物理量。")}</h2><p>{T("A field needs coordinates, sampling, phase and normalization. A circuit needs port modes and reference planes. A material needs its source and spectral range. Preserve these with each model and result.","复场需要坐标、采样、相位和归一化；电路需要端口模态与参考面；材料需要数据来源和谱域。模型与结果一起保留这些信息。")}</p></div></section>'
 results=start(5)+f'<p class="lead">{T("Submit a complete program or a dependency graph. Independent workers continue after the Agent disconnects; reconnect using the same research run ID.","提交完整程序或有依赖关系的工作流。后台进程在 Agent 断开后继续运行；再次连接时用同一个研究任务编号读取进度与结果。")}</p>'
 results+=code('optics-photonics submit tmm --program research.py --inputs "@inputs.json" --request-id study-001\noptics-photonics status RUN_ID\noptics-photonics files RUN_ID\noptics-photonics read RUN_ID calculate/attempt-1/result.json\noptics-photonics download RUN_ID calculate/attempt-1/spectrum.csv spectrum.csv')
 pairs=[(T('Native program','原生研究程序'),T('INPUTS supplies JSON parameters. OUTPUT_DIR stores arrays and models. RESULT returns compact JSON.','INPUTS 提供 JSON 参数，OUTPUT_DIR 保存数组和模型，RESULT 返回简洁 JSON。')),(T('Parallel and sequential','并行与串行'),T('Independent steps can run concurrently. Dependencies set order; bindings transfer selected outputs into the next inputs. Keep a persistent solver session in one program.','独立步骤可以并行；依赖决定顺序，bindings 将指定结果传入后续步骤；持续使用的求解器会话放在同一程序中。')),(T('Resources','计算资源'),T('CPU and named GPU/license capacities coordinate all submitted runs. Each environment declares threads, concurrency and resource requirements. The native program selects actual GPUs, MPI ranks and cluster queues.','CPU 与命名的 GPU、许可额度协调所有研究任务；每个环境声明线程、并发数与资源需求。实际 GPU、MPI 进程和集群队列由原生程序选择。')),(T('Scientific records','科学记录'),T('Inputs, source, software versions, environment settings, results and native data files stay together. Written files can be read while other calculations continue.','输入、程序、软件版本、环境设置、结果与科学文件一起保存。其他步骤仍在计算时，也可读取已经写出的文件。'))]
 results+='<div class="steps">'+''.join(f'<div class="step"><div><h3>{a}</h3><p>{b}</p></div></div>' for a,b in pairs)+'</div>'
 results+=f'<p class="note">{T("Resume preserves completed steps and reruns unfinished steps in a new attempt directory. Append new steps to the same run. Native solver checkpoints and remote task IDs remain part of the research program.","继续任务时保留已完成步骤，未完成步骤写入新的运行目录；也可以向同一任务追加后续步骤。求解器内部检查点与远程任务编号由研究程序保存和使用。")}</p></section>'
 js=r'''const DATA=JSON.parse(document.querySelector('#data').textContent), CONN=JSON.parse(document.querySelector('#connections').textContent);const INDEX=JSON.parse(document.querySelector('#search-index').textContent), normalize=s=>s.normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function page(id){if(document.getElementById(id)?.tagName!=='SECTION')id='overview';document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===id);b.setAttribute('aria-current',b.dataset.page===id?'page':'false')});history.replaceState(null,'','#'+id);window.scrollTo(0,0)}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));function render(){let q=normalize($('#query').value).split(' ').filter(Boolean),group=$('#license').value,domain=$('#domain').value,route=$('#route').value;let rows=DATA.filter(d=>(!group||d.group===group)&&(!domain||d.cats.includes(domain))&&(!route||(route==='executed'?CONN[d.id].operations.length:route==='session'?CONN[d.id].session_adapter:CONN[d.id].kind===route))&&q.every(term=>INDEX[d.id].includes(term)));$('#count').textContent=rows.length+' / '+DATA.length;$('#cards').innerHTML=rows.map(d=>{let c=CONN[d.id],run=c.operations.length;return '<article class="software"><small>'+esc(d.group)+' · '+esc(c.kind)+'</small><h3>'+esc(d.name)+'</h3><p>'+esc(d.summary)+'</p>'+(c.session_adapter?'<span class="pill">'+SESSION_LABEL+'</span>':'')+(run?'<span class="pill">'+LABEL+' · '+esc(c.operations.join(', '))+'</span>':'')+'<details><summary>'+DETAILS+'</summary><p>'+esc(c.interface)+'</p><p>'+esc(d.compute)+'</p><p>'+esc(d.license)+'</p>'+d.sources.map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.label)+'</a>').join(' · ')+(c.upstream.mcp.url?'<p>MCP: <a href="'+esc(c.upstream.mcp.url)+'">'+esc(c.upstream.mcp.text)+'</a></p>':'')+(c.upstream.skill.url?'<p>Skill: <a href="'+esc(c.upstream.skill.url)+'">'+esc(c.upstream.skill.text)+'</a></p>':'')+'</details></article>'}).join('')};['query','license','domain','route'].forEach(id=>$('#'+id).addEventListener('input',render));render();page(location.hash.slice(1)||'overview');'''
 js='const SESSION_LABEL='+json.dumps(T('Native session adapter','原生会话连接器'))+';const LABEL='+json.dumps(T('Executable calculation','可执行计算'))+', DETAILS='+json.dumps(T('Interface, license and sources','接口、许可与资料'))+';'+js
 logo='<svg width="34" height="34" viewBox="0 0 28 28" aria-hidden="true"><g fill="#b99553"><ellipse cx="14" cy="8" rx="4" ry="6"/><ellipse cx="20" cy="14" rx="6" ry="4"/><ellipse cx="14" cy="20" rx="4" ry="6"/><ellipse cx="8" cy="14" rx="6" ry="4"/></g><circle cx="14" cy="14" r="3" fill="#eeeee6"/></svg>'
 serialize=lambda x:json.dumps(x,ensure_ascii=False).replace('</','<\\/')
 content=f'<!doctype html><html lang="{T("en","zh-CN")}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Optics &amp; Photonics · {T("Connections","软件接入")}</title><style>{CSS}</style><noscript><style>section[hidden]{{display:block!important}}nav{{display:none}}</style></noscript></head><body><aside><div class="brand">{logo}Optics &amp; Photonics</div><div class="edition">CONNECTIONS / {__version__}</div><nav>{nav}</nav><footer>Field · Matter · Interaction<br>2026.11.11</footer></aside><main><header><span>SOFTWARE · METHODS · EXECUTION</span><div><a href="{T("connect.zh.html","connect.html")}">{T("中文","English")}</a> · <a href="{T("catalogue.html","catalogue.zh.html")}">{T("Catalogue","软件目录")}</a> · <a href="https://github.com/Cherish0925/Optics-Photonics-AI-Lab">GitHub ↗</a></div></header>{overview}{install}{hosts}{software}{methods}{results}<div class="bottom">Optics &amp; Photonics {__version__} · <a href="https://github.com/Cherish0925/Optics-Photonics-AI-Lab/releases">{T("Downloads","下载发布包")}</a> · MIT</div></main><script id="search-index" type="application/json">{serialize(search_index())}</script><script id="data" type="application/json">{serialize(data)}</script><script id="connections" type="application/json">{serialize(connections)}</script><script>{js}</script></body></html>'
 target=ROOT/'docs'/T('connect.html','connect.zh.html');target.write_text(content,encoding='utf-8')
 (ROOT/'docs'/T('index.html','index.zh.html')).write_text(content,encoding='utf-8')
 print(target.name,len(content))

